+const DANGEROUS_ELEMENTS = [
+    'animate',
+    'animatemotion',
+    'animatetransform',
+    'discard',
+    'foreignobject',
+    'handler',
+    'script',
+    'set'
+];
+
+const EVENT_HANDLER_ATTRIBUTE = /^on/i;
+
+const normalizeUrl = function (url) {
+    return String(url)
+        .replace(/[\u0000-\u001F\u007F\s]+/g, '')
+        .toLowerCase();
+};
+
+const isDangerousUrl = function (url) {
+    const normalized = normalizeUrl(url);
+    return normalized.indexOf('javascript:') === 0 ||
+        normalized.indexOf('vbscript:') === 0 ||
+        normalized.indexOf('data:text/html') === 0 ||
+        normalized.indexOf('data:image/svg+xml') === 0;
+};
+
+const containsDangerousCssUrl = function (value) {
+    const normalized = normalizeUrl(value);
+    return /url\((?:'|")?(?:javascript:|vbscript:|data:text\/html|data:image\/svg\+xml)/.test(normalized);
+};
+
+/**
+ * Remove active content from untrusted SVG. Scratch projects may contain SVG
+ * assets supplied by users, so they must not be allowed to execute script when
+ * parsed or rendered in the DOM.
+ * @param {Element} element SVG DOM element to sanitize.
+ */
+const sanitizeSvg = function (element) {
+    if (!element) return;
+
+    if (element.attributes) {
+        const attributes = Array.prototype.slice.call(element.attributes);
+        for (let i = 0; i < attributes.length; i++) {
+            const attribute = attributes[i];
+            const attributeName = attribute.name.toLowerCase();
+            const localName = attribute.localName.toLowerCase();
+
+            if (EVENT_HANDLER_ATTRIBUTE.test(attributeName) ||
+                    ((localName === 'href' || localName === 'src') && isDangerousUrl(attribute.value)) ||
+                    containsDangerousCssUrl(attribute.value)) {
+                element.removeAttribute(attribute.name);
+            }
+        }
+    }
+
+    if (!element.childNodes) return;
+
+    const childNodes = Array.prototype.slice.call(element.childNodes);
+    for (let i = 0; i < childNodes.length; i++) {
+        const child = childNodes[i];
+        if (child.nodeType !== 1) continue;
+
+        const tagName = child.localName.toLowerCase();
+        if (DANGEROUS_ELEMENTS.indexOf(tagName) !== -1) {
+            child.parentNode.removeChild(child);
+            continue;
+        }
