+    pub(crate) fn verify_report(&self, report: &ReportBody) -> Result<()> {
+        let identity = &self.enclave_identity;
+
+        let miscselect = parse_hex_u32(&identity.miscselect)?;
+        let miscselect_mask = parse_hex_u32(&identity.miscselect_mask)?;
+        if (report.misc_select & miscselect_mask) != (miscselect & miscselect_mask) {
+            return Err(Error::InvalidQeReportIdentity);
+        }
+
+        let attributes = parse_hex_array::<16>(&identity.attributes)?;
+        let attributes_mask = parse_hex_array::<16>(&identity.attributes_mask)?;
+        for i in 0..16 {
+            if (report.attributes[i] & attributes_mask[i]) != (attributes[i] & attributes_mask[i])
+            {
+                return Err(Error::InvalidQeReportIdentity);
+            }
+        }
+
+        let mrsigner = parse_hex_array::<32>(&identity.mrsigner)?;
+        if report.mr_signer != mrsigner {
+            return Err(Error::InvalidQeReportIdentity);
+        }
+
+        if report.isv_prod_id != identity.isv_prod_id {
+            return Err(Error::InvalidQeReportIdentity);
+        }
+
+        /*
+         * The QE report must correspond to an acceptable QE TCB level from the
+         * signed QE identity collateral. Without this check, a quote signed by a
+         * malicious/non-Intel QE can be accepted as long as the rest of the
+         * quote signature chain is syntactically valid.
+         */
+        let accepted_tcb = identity.tcb_levels.iter().any(|level| {
+            report.isv_svn >= level.tcb.isv_svn
+                && matches!(
+                    level.tcb_status.as_str(),
+                    "UpToDate"
+                        | "ConfigurationNeeded"
+                        | "SWHardeningNeeded"
+                        | "ConfigurationAndSWHardeningNeeded"
+                )
+        });
+
+        if !accepted_tcb {
+            return Err(Error::InvalidQeReportIdentity);
+        }
+
+        Ok(())
+    }
+}
+
+fn parse_hex_u32(s: &str) -> Result<u32> {
+    u32::from_str_radix(s, 16).map_err(|_| Error::InvalidQeIdentity)
+}
+
+fn parse_hex_array<const N: usize>(s: &str) -> Result<[u8; N]> {
+    let bytes = hex::decode(s).map_err(|_| Error::InvalidQeIdentity)?;
+    if bytes.len() != N {
+        return Err(Error::InvalidQeIdentity);
+    }
+
+    let mut out = [0u8; N];
+    out.copy_from_slice(&bytes);
+    Ok(out)
+}
