+package org.apache.streampipes.manager.endpoint.security;
+
+import java.net.IDN;
+import java.net.Inet4Address;
+import java.net.Inet6Address;
+import java.net.InetAddress;
+import java.net.URI;
+import java.net.URISyntaxException;
+import java.net.UnknownHostException;
+import java.util.Locale;
+
+public final class EndpointUrlValidator {
+
+  private EndpointUrlValidator() {
+  }
+
+  public static String validate(String endpointUrl) {
+    try {
+      var uri = new URI(endpointUrl).normalize();
+
+      validateScheme(uri);
+      validateAuthority(uri);
+      validateHost(uri.getHost());
+
+      return uri.toASCIIString();
+    } catch (URISyntaxException e) {
+      throw new IllegalArgumentException("Invalid endpoint URL", e);
+    }
+  }
+
+  private static void validateScheme(URI uri) {
+    var scheme = uri.getScheme();
+    if (scheme == null) {
+      throw new IllegalArgumentException("Endpoint URL must be absolute");
+    }
+
+    var normalizedScheme = scheme.toLowerCase(Locale.ROOT);
+    if (!"http".equals(normalizedScheme) && !"https".equals(normalizedScheme)) {
+      throw new IllegalArgumentException("Only HTTP(S) endpoint URLs are allowed");
+    }
+  }
+
+  private static void validateAuthority(URI uri) {
+    if (uri.getHost() == null) {
+      throw new IllegalArgumentException("Endpoint URL must contain a host");
+    }
+
+    if (uri.getUserInfo() != null) {
+      throw new IllegalArgumentException("Endpoint URL must not contain user info");
+    }
+  }
+
+  private static void validateHost(String host) {
+    try {
+      var asciiHost = IDN.toASCII(host);
+      for (var address : InetAddress.getAllByName(asciiHost)) {
+        if (isForbiddenAddress(address)) {
+          throw new IllegalArgumentException("Endpoint URL resolves to a forbidden address");
+        }
+      }
+    } catch (UnknownHostException e) {
+      throw new IllegalArgumentException("Endpoint URL host could not be resolved", e);
+    }
+  }
+
+  private static boolean isForbiddenAddress(InetAddress address) {
+    return address.isAnyLocalAddress()
+        || address.isLoopbackAddress()
+        || address.isLinkLocalAddress()
+        || address.isSiteLocalAddress()
+        || address.isMulticastAddress()
+        || isUniqueLocalAddress(address);
+  }
+
+  private static boolean isUniqueLocalAddress(InetAddress address) {
+    if (address instanceof Inet6Address) {
+      var bytes = address.getAddress();
+      return (bytes[0] & 0xfe) == 0xfc;
+    }
+
+    return address instanceof Inet4Address && address.getHostAddress().startsWith("0.");
+  }
+}

