new file mode 100644
index 00000000..8d5b4f9a
--- /dev/null
+++ b/lib/runtime/safePattern.ts
@@ -0,0 +1,108 @@
+import {_} from "../compile/codegen"
+
+const MAX_PATTERN_LENGTH = 1024
+
+export default function safePattern(pattern: string, flags: string): boolean {
+  if (pattern.length > MAX_PATTERN_LENGTH) return false
+
+  try {
+    new RegExp(pattern, flags)
+  } catch (e) {
+    return false
+  }
+
+  return !hasUnsafeQuantifiedGroup(pattern)
+}
+
+;(safePattern as any).code = _`require("ajv/dist/runtime/safePattern").default`
+
+function hasUnsafeQuantifiedGroup(pattern: string): boolean {
+  const groups: {hasAlt: boolean; hasQuantifier: boolean}[] = []
+
+  for (let i = 0; i < pattern.length; i++) {
+    const ch = pattern[i]
+
+    if (ch === "\\") {
+      i++
+      continue
+    }
+
+    if (ch === "[") {
+      i = skipCharClass(pattern, i)
+      continue
+    }
+
+    if (ch === "(") {
+      groups.push({hasAlt: false, hasQuantifier: false})
+      if (pattern[i + 1] === "?") i++
+      continue
+    }
+
+    if (ch === "|") {
+      const group = groups[groups.length - 1]
+      if (group) group.hasAlt = true
+      continue
+    }
+
+    if (ch === ")") {
+      const group = groups.pop()
+      if (!group) continue
+
+      const quantifier = quantifierAt(pattern, i + 1)
+      if (quantifier) {
+        if (group.hasQuantifier || (group.hasAlt && quantifier.repeat)) return true
+
+        const parent = groups[groups.length - 1]
+        if (parent) parent.hasQuantifier = true
+        i = quantifier.end
+      }
+      continue
+    }
+
+    const quantifier = quantifierAt(pattern, i)
+    if (quantifier) {
+      const group = groups[groups.length - 1]
+      if (group) group.hasQuantifier = true
+      i = quantifier.end
+    }
+  }
+
+  return false
+}
+
+function skipCharClass(pattern: string, i: number): number {
+  for (i++; i < pattern.length; i++) {
+    if (pattern[i] === "\\") {
+      i++
+    } else if (pattern[i] === "]") {
+      return i
+    }
+  }
+  return i
+}
+
+function quantifierAt(pattern: string, i: number): {end: number; repeat: boolean} | undefined {
+  const ch = pattern[i]
+
+  if (ch === "*" || ch === "+") return {end: i, repeat: true}
+  if (ch === "?") return {end: i, repeat: false}
+  if (ch !== "{") return undefined
+
+  let j = i + 1
+  if (!isDigit(pattern[j])) return undefined
+
+  while (isDigit(pattern[j])) j++
+
+  let repeat = false
+  if (pattern[j] === ",") {
+    repeat = true
+    j++
+    while (isDigit(pattern[j])) j++
+  }
+
+  if (pattern[j] !== "}") return undefined
+  return {end: j, repeat}
+}
+
+function isDigit(ch: string): boolean {
+  if (!ch) return false
+  const c = ch.charCodeAt(0)
+  return c >= 48 && c <= 57
+}
